cypher:
MATCH (a:Actor)-[:ACTED_IN]->(m:Movie)<-[r:RATED]-(u:User)
WHERE r.rating > 4
RETURN DISTINCT a.name;

MATCH (m:Movie)
WHERE NOT EXISTS {
  MATCH (:User {name: "Robert Brooks"})-[:RATED]->(m)
}
RETURN m.title;

MATCH (a:Actor {name: "Robert De Niro"})-[:ACTED_IN]->(m:Movie)<-[:ACTED_IN]-(coactor:Actor)
WHERE coactor <> a
RETURN m.title AS movie, COLLECT(DISTINCT coactor.name) AS coactors;
